SELECT percentile_cont(0.75) within GROUP (ORDER BY value) - percentile_cont(0.25) within GROUP (ORDER BY value) AS interquartile_range, median(value) AS median_value FROM labevents JOIN patients ON labevents.subject_id = patients.subject_id JOIN admissions ON labevents.subject_id = admissions.subject_id WHERE patients.gender = 'M' AND patients.anchor_age = 48 AND admissions.admission_type = 'ACS' AND itemid = 757071 AND value > percentile_cont(0.99) within GROUP (ORDER BY value);